command:
/**
 * Teleport。
 */

(async () => {
  const RANGE_FT = 60;      // 傳送範圍（英尺）
  const TIMEOUT  = 20000;   // 單次點擊超時時間（毫秒）
  const COLOR    = 0x66ccff;

  // 取得單一目標（優先 game.user.targets，其次 canvas.tokens.controlled）
  const pickTarget = () => {
    const tarr = Array.from(game.user.targets ?? []);
    if (tarr.length === 1) return tarr[0];
    const ctrl = canvas.tokens.controlled;
    if (ctrl && ctrl.length === 1) return ctrl[0];
    return null;
  };
  const token = pickTarget();
  if (!token) {
    ui.notifications.warn("請先 target（或控制）一個 Token，然後運行宏。");
    return;
  }

  const gridSize = canvas.grid.size;
  const feetPerSquare = canvas.scene.grid?.distance ?? 5;
  const maxSquares = Math.max(1, Math.floor(RANGE_FT / feetPerSquare));
  const radiusPx = maxSquares * gridSize;

  // 計算 token 當前視覺中心（避免使用已棄用的 API）
  const originCenter = { x: (token.center?.x ?? (token.x + token.w / 2)), y: (token.center?.y ?? (token.y + token.h / 2)) };

  // 繪製高亮圓
  const g = new PIXI.Graphics();
  g.lineStyle(2, COLOR, 0.9);
  g.beginFill(COLOR, 0.08);
  g.drawCircle(originCenter.x, originCenter.y, radiusPx);
  g.endFill();
  g.zIndex = 9999;
  canvas.app.stage.addChild(g);

  ui.notifications.info(`請在高亮圓內點擊傳送落點（最多 ${RANGE_FT} 英尺）；超出或佔用會提示並要求重選。）`);

  // 等待點擊並返回 snapped center（格子中心點）
  const waitClickAndSnapCenter = (ms) => new Promise(resolve => {
    const handler = (event) => {
      try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
      let pos = null;
      try { pos = event.data.getLocalPosition(canvas.app.stage); } catch(e){ pos = null; }
      if (!pos) return resolve(null);
      // 使用 BaseGrid#getSnappedPoint 獲取格子中心（CENTER 模式）
      try {
        const snappedCenter = canvas.grid.getSnappedPoint({ x: pos.x, y: pos.y }, { mode: CONST.GRID_SNAPPING_MODES.CENTER });
        return resolve(snappedCenter);
      } catch (err) {
        // fallback：四捨五入到網格中心
        const sx = Math.round(pos.x / gridSize) * gridSize;
        const sy = Math.round(pos.y / gridSize) * gridSize;
        return resolve({ x: sx, y: sy });
      }
    };
    canvas.app.stage.on("pointerdown", handler);
    setTimeout(() => {
      try { canvas.app.stage.off("pointerdown", handler); } catch(e){}
      resolve(null);
    }, ms);
  });

  // token 在 Scene 中以 grid 單位的寬高（整數）
  const tokenGridW = Number(token.document.width ?? token.document._source?.width ?? 1);
  const tokenGridH = Number(token.document.height ?? token.document._source?.height ?? tokenGridW);

  // 主循環：直到選出合法落點
  while (true) {
    // 確保高亮仍在舞臺
    if (!canvas.app.stage.children.includes(g)) canvas.app.stage.addChild(g);

    const snappedCenter = await waitClickAndSnapCenter(TIMEOUT);
    if (!snappedCenter) {
      ui.notifications.warn("未檢測到點擊，請再試一次。");
      continue;
    }

    // 由 snapped center 推斷所在格索引（左上格索引 = floor(center / gridSize)）
    const clickedCol = Math.floor(snappedCenter.x / gridSize);
    const clickedRow = Math.floor(snappedCenter.y / gridSize);

    // 計算 token 的左上格列/行：保證 clicked cell 在 token 佔據區域中心附近
    const topLeftCol = clickedCol - Math.floor(tokenGridW / 2);
    const topLeftRow = clickedRow - Math.floor(tokenGridH / 2);

    // 計算 token 的目標中心（舞臺座標）
    const centerX = (topLeftCol + tokenGridW / 2) * gridSize;
    const centerY = (topLeftRow + tokenGridH / 2) * gridSize;

    // 計算距離（以英尺）
    const distFt = Math.hypot(centerX - originCenter.x, centerY - originCenter.y) / gridSize * feetPerSquare;
    if (distFt > RANGE_FT + 0.001) {
      ui.notifications.warn(`選擇超出 ${RANGE_FT} 英尺（距離 ${Math.round(distFt)}ft），請重新選擇。`);
      continue;
    }

    // 目標左上角像素（用於碰撞檢測）
    const destTopLeftX = Math.round(topLeftCol * gridSize);
    const destTopLeftY = Math.round(topLeftRow * gridSize);
    const destRect = new PIXI.Rectangle(destTopLeftX, destTopLeftY, tokenGridW * gridSize, tokenGridH * gridSize);

    // 碰撞檢測：若任一現有 token 與該矩形重疊，視爲被佔用
    const occupied = canvas.tokens.placeables.some(t => {
      if (t.id === token.id) return false;
      const r = new PIXI.Rectangle(t.x, t.y, t.w, t.h);
      return destRect.right  > r.left &&
             destRect.left   < r.right &&
             destRect.bottom > r.top &&
             destRect.top    < r.bottom;
    });
    if (occupied) {
      ui.notifications.warn("該位置被佔用，請選擇其它位置。");
      continue;
    }

    // 清理高亮
    try { canvas.app.stage.removeChild(g); } catch(e){}

    // 使用 MidiQOL.moveToken，傳入 center 座標，第三參數 false（無動畫）
    if (typeof MidiQOL?.moveToken === "function") {
      try {
        await MidiQOL.moveToken(token, { x: Math.round(centerX), y: Math.round(centerY) }, false);
        ui.notifications.info(`${token.name} 已被傳送（無動畫）。`);
        console.log(`RealityCollapse: teleported ${token.name} -> center=(${Math.round(centerX)},${Math.round(centerY)}), topLeft=(${destTopLeftX},${destTopLeftY}), grid=${tokenGridW}x${tokenGridH}`);
        return;
      } catch (e) {
        console.error("RealityCollapse: MidiQOL.moveToken failed", e);
        ui.notifications.error("傳送失敗（查看控制檯）");
        return;
      }
    } else {
      ui.notifications.error("MidiQOL.moveToken 不可用——宏配置爲僅使用 MidiQOL.moveToken 進行傳送。");
      return;
    }
  }
})();
